contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = c.getBalance(address(this));
        require(balBefore == 0);
        // Withdrawing with a zero balance must revert.
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        // A successful withdrawal with zero balance would also change nothing,
        // but the rule is it must revert; the Ether in the contract must stay put either way.
        uint contractBal = address(c).balance;
        assert(reverted || c.getBalance(address(this)) == balBefore);
        assert(contractBal == address(c).balance);
    }
    receive() external payable { }
}

